use "./column.css"
use Card from "./card.qubc"

component Column {
  props {
    name: string,
    accent: string,
    position: number,
    cards: Omit<Card, 'seat'>[]
  }
  contexts {
    LaneArea { lane: name, position: position }
  }
  events {
    CLICK_ADD_CARD({ lane: name })
    CLICK_HEADING({ lane: name, position })
    CLICK_REMOVE_CARD({ lane: name })
  }
  template {
    div(class="col") {
      header(class="col__head" style={accent}) {
        h2(class="col__name" @click:CLICK_HEADING) { {name} }
      }

      @with LaneArea {
        div(class="col__cards") {
          @for (card, seat of cards) {
            div(class="col__slot") {
              Ticket: Card(
                title={card.title}
                assignee={card.assignee}
                points={card.points}
                urgent={card.urgent}
                seat={seat}
              /)
              button(class="col__remove" @click:CLICK_REMOVE_CARD) { "x" }
            }
          }
        }
      }

      button(class="col__add" @click:CLICK_ADD_CARD) { "+ 카드" }
    }
  }
}

const OWNERS = ["지현", "민수", "서연", "도윤"];
const POINTS = ["1", "2", "3", "5", "8", "13"];

const next = (list, current) => list[(list.indexOf(current) + 1) % list.length];

let made = 0;

export default {
  CLICK_ADD_CARD: (data, { props, push }) => {
    made += 1;
    push(props.cards, {
      title: `새 카드 ${made}`,
      assignee: OWNERS[made % OWNERS.length],
      points: "1",
      urgent: false,
    });
    console.log("카드 추가:", data.lane);
  },

  // @for 직속 element라 익명 세그먼트가 붙는다. 배열(props.cards)을 가진 Column이 쏜다.
  "[$0].CLICK_REMOVE_CARD": (data, { props, removeAt, $0 }) => {
    removeAt(props.cards, $0);
    console.log(`카드 제거: ${data.lane} ${$0}번째`);
  },

  CLICK_HEADING: (data) => {
    console.log("컬럼 제목:", data.lane, "/ 자리:", data.position);
  },

  "Ticket[$0].CLICK_CARD": (data, { $0, context }) => {
    console.log(`카드: ${data.title} (${$0}번째)`);
    console.log("  레인:", context.LaneArea.lane);
  },

  "Ticket[$0].CLICK_OWNER": (data, { props, set }) => {
    const owner = next(OWNERS, data.assignee);
    set(props.assignee, owner);
    console.log("담당자:", data.assignee, "->", owner);
  },

  "Ticket[$0].Flag.CLICK_BADGE": (data) => {
    console.log("긴급 배지:", data.text);
  },

  "Ticket[$0].Points.CLICK_BADGE": (data, { props, set }) => {
    const points = next(POINTS, data.text);
    set(props.text, points);
    console.log("포인트:", data.text, "->", points);
  },
};

.col {
  width: 216px;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  border-radius: 8px;
  background: #ebecf0;
  padding: 10px;
}

.col__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  padding: 6px 8px;
  border-radius: 6px;
}

.col__name {
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
}

.col__cards {
  flex: 1;
  min-height: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.col__add {
  width: 100%;
  margin-top: 8px;
  padding: 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: #5e6c84;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}

.col__add:hover {
  background: #dfe1e6;
  color: #172b4d;
}

/* 카드 한 자리 - 카드와 제거 버튼을 겹친다. 버튼은 hover할 때만 보인다. */

.col__slot {
  position: relative;
}

.col__remove {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 20px;
  height: 20px;
  display: none;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: #fff;
  color: #6b778c;
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
}

.col__slot:hover .col__remove {
  display: block;
}

.col__remove:hover {
  background: #ffebe6;
  color: #bf2600;
}

