use "./card.css"
use Badge from "./badge.qubc"

component Card {
  props {
    title: string,
    assignee: string,
    points: string,
    urgent: bool,
    seat: number
  }
  events {
    CLICK_CARD({ title, seat })
    CLICK_OWNER({ title, assignee })
  }
  template {
    article(class="ticket" @click:CLICK_CARD) {
      @if (urgent) {
        Flag: Badge(text="긴급" tone="hot" /)
      }

      h3(class="ticket__title") { {title} }

      footer(class="ticket__foot") {
        button(class="ticket__who" @click:CLICK_OWNER) { {assignee} }
        Points: Badge(text={points} tone="calm" /)
      }
    }
  }
}

const OWNERS = ["지현", "민수", "서연", "도윤"];
const POINTS = ["1", "2", "3", "5", "8", "13"];

const next = (list, current) => list[(list.indexOf(current) + 1) % list.length];

export default {
  CLICK_CARD: (data) => {
    console.log("카드:", data.title, "/ 자리:", data.seat);
  },

  CLICK_OWNER: (data, { props, set }) => {
    const owner = next(OWNERS, data.assignee);
    set(props.assignee, owner);
    console.log("담당자:", data.assignee, "->", owner);
  },

  "Flag.CLICK_BADGE": (data) => {
    console.log("긴급 배지:", data.text, data.tone);
  },

  "Points.CLICK_BADGE": (data, { props, set }) => {
    const points = next(POINTS, data.text);
    set(props.text, points);
    console.log("포인트:", data.text, "->", points);
  },
};

