  border: 0;
  border-radius: 10px;
  background: #dfe1e6;
  color: #42526e;
  font-size: 12px;
  cursor: pointer;
}

.ticket__who:hover {
  background: #c1c7d0;
}

use "./badge.css"

component Badge {
  props { text: string, tone: string }
  events { CLICK_BADGE({ text, tone }) }
  template {
    span(class="badge" data-tone={tone} @click:CLICK_BADGE) { {text} }
  }
}

const TONES = ["hot", "calm"];

export default {
  CLICK_BADGE: (data, { props, set }) => {
    const tone = TONES[(TONES.indexOf(data.tone) + 1) % TONES.length];
    set(props.tone, tone);
    console.log("배지:", data.text, "/ 톤:", data.tone, "->", tone);
  },
};

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.badge[data-tone="hot"] {
  background: #ffebe6;
  color: #bf2600;
}

.badge[data-tone="calm"] {
  background: #deebff;
  color: #0747a6;
}
